class TestACLMaxUserIP : public CPPUNIT_NS::TestFixture
{
    CPPUNIT_TEST_SUITE(TestACLMaxUserIP);
    /* note the statement here and then the actual prototype below */
    CPPUNIT_TEST(testDefaults);
