    /// \returns (linked) "line" Options supported by this Acl::Node
    /// \see Acl::Node::options()
    virtual const Acl::Options &lineOptions() { return Acl::NoOptions(); }

    static void ParseNamed(ConfigParser &, NamedAcls &, const SBuf &name);
};

