UserDomainAclData::match(const char *user, const char *host) const
{
    if (!compiled_ || !user || !host || !*user || !*host)
        return false;

    for (const auto &rule: rules_) {
        if (userMatches(rule, user) && domainMatches(rule, host))
            return true;
    }

    return false;
}

