    static bool domainMatches(const Rule &rule, const char *host);

    Acl::BooleanOption caseSensitivity_;
    Acl::BooleanOptionValue caseInsensitive_;
    Acl::Options lineOptions_;
    std::vector<Rule> rules_;
    bool invalid_ = false;
    bool compiled_ = false;
};

